-- 取回 sorted
WITH "base" AS (SELECT "ds_orders"."Row ID" AS "f_row_id", "ds_orders"."Order ID" AS "f_order_id", "ds_orders"."Order Date" AS "f_order_date", "ds_orders"."Ship Date" AS "f_ship_date", "ds_orders"."Ship Mode" AS "f_ship_mode", "ds_orders"."Customer ID" AS "f_customer_id", "ds_orders"."Customer Name" AS "f_customer_name", "ds_orders"."Segment" AS "f_segment", "ds_orders"."Country/Region" AS "f_country_region", "ds_orders"."City" AS "f_city", "ds_orders"."State/Province" AS "f_state_province", "ds_orders"."Postal Code" AS "f_postal_code", "ds_orders"."Region" AS "f_region", "ds_orders"."Product ID" AS "f_product_id", "ds_orders"."Category" AS "f_category", "ds_orders"."Sub-Category" AS "f_sub_category", "ds_orders"."Product Name" AS "f_product_name", "ds_orders"."Sales" AS "f_sales", "ds_orders"."Quantity" AS "f_quantity", "ds_orders"."Discount" AS "f_discount", "ds_orders"."Profit" AS "f_profit" FROM "sales"."ds_orders" AS "ds_orders"), "src" AS (SELECT * FROM "base" WHERE ("f_country_region" IN ('United States'))), "lod" AS (SELECT "f_sub_category" AS "__d0", "f_order_id" AS "__d1", SUM("f_profit") AS "__v" FROM "src" GROUP BY 1, 2), "dimf_ext" AS (SELECT "r".*, "l0"."__v" AS "__lod_0" FROM "src" AS "r" LEFT JOIN "lod" AS "l0" ON DECODE("r"."f_sub_category", "l0"."__d0", 1, 0) = 1 AND DECODE("r"."f_order_id", "l0"."__d1", 1, 0) = 1), "agg" AS (SELECT "f_sub_category" AS "__k0", SUM("f_profit") AS "__a0" FROM "dimf_ext" GROUP BY 1), "combos" AS (SELECT DISTINCT "f_sub_category" AS "__g0", "f_order_id" AS "__g1", "__lod_0" FROM "dimf_ext"), "combo_agg" AS (SELECT "__g0" AS "__k0", AVG("__lod_0") AS "__a1" FROM "combos" GROUP BY 1), "agg_1" AS (SELECT "b".*, "c0"."__a1" FROM "agg" AS "b" LEFT JOIN "combo_agg" AS "c0" ON DECODE("b"."__k0", "c0"."__k0", 1, 0) = 1), "meas" AS (SELECT "agg_1".*, "__a0" AS "__m0", ("__a1") AS "__m2" FROM "agg_1"), "sort_agg" AS (SELECT "f_sub_category" AS "__k0", SUM("f_profit") AS "__a0" FROM "dimf_ext" GROUP BY 1), "sort" AS (SELECT "__k0" AS "__key", "__a0" AS "__v" FROM "sort_agg"), "sorted" AS (SELECT "m".*, "s0"."__v" AS "__sort0" FROM "meas" AS "m" LEFT JOIN "sort" AS "s0" ON DECODE("s0"."__key", "m"."__k0", 1, 0) = 1) SELECT * FROM "sorted"
